-- Probes are diagnostics, not sessions (ADR-0039): keep them out of the session view even if a
-- cleanup fails, so they can never look like a person or an unidentified run.

CREATE OR REPLACE VIEW cardo.silver_session (`session_id` String, `pseudonym` Nullable(String), `salt_version` String, `cohort` String, `app_version` String, `terminal_type` String, `start_type` String, `started_at` DateTime64(9), `last_event_at` DateTime64(9), `day` Date, `clock` String, `ended` UInt8, `end_reason` String, `has_otel` UInt8, `has_hooks` UInt8, `actor_kind` String, `workflow` String) AS SELECT session_id, nullIf(anyIf(e_pseudonym, e_pseudonym != ''), '') AS pseudonym, anyIf(e_salt_version, (e_salt_version != '') AND (e_clock != 'collector')) AS salt_version, anyIf(e_cohort, e_cohort != '') AS cohort, anyIf(e_app_version, e_app_version != '') AS app_version, anyIf(e_terminal_type, e_terminal_type != '') AS terminal_type, anyIf(e_start_type, e_start_type != '') AS start_type, multiIf(countIf(e_clock = 'client') > 0, minIf(e_ts, e_clock = 'client'), countIf(e_clock = 'collector') > 0, minIf(e_ts, e_clock = 'collector'), min(e_ts)) AS started_at, multiIf(countIf(e_clock = 'client') > 0, maxIf(e_ts, e_clock = 'client'), countIf(e_clock = 'collector') > 0, maxIf(e_ts, e_clock = 'collector'), max(e_ts)) AS last_event_at, toDate(started_at) AS day, if(countIf(e_clock = 'client') > 0, 'client', 'collector') AS clock, countIf(e_event = 'SessionEnd') > 0 AS ended, anyIf(e_end_reason, e_end_reason != '') AS end_reason, countIf(e_clock = 'client') > 0 AS has_otel, countIf(e_clock = 'collector') > 0 AS has_hooks, if(anyIf(svc_kind, svc_kind != '') = 'service', 'service', 'person') AS actor_kind, anyIf(svc_workflow, svc_workflow != '') AS workflow FROM (SELECT LogAttributes['session.id'] AS session_id, if((LogAttributes['user.pseudonym']) != '', LogAttributes['user.pseudonym'], ResourceAttributes['user.pseudonym']) AS e_pseudonym, ResourceAttributes['cardo.salt_version'] AS e_salt_version, if((ResourceAttributes['cardo.cohort']) != '', ResourceAttributes['cardo.cohort'], LogAttributes['cardo.cohort']) AS e_cohort, LogAttributes['app.version'] AS e_app_version, LogAttributes['terminal.type'] AS e_terminal_type, '' AS e_start_type, Timestamp AS e_ts, 'client' AS e_clock, EventName AS e_event, '' AS e_end_reason FROM cardo.bronze_otel_logs WHERE (LogAttributes['session.id']) != '' UNION ALL SELECT Attributes['session.id'], if((Attributes['user.pseudonym']) != '', Attributes['user.pseudonym'], ResourceAttributes['user.pseudonym']), ResourceAttributes['cardo.salt_version'], if((ResourceAttributes['cardo.cohort']) != '', ResourceAttributes['cardo.cohort'], Attributes['cardo.cohort']), Attributes['app.version'], Attributes['terminal.type'], Attributes['start_type'], toDateTime64(TimeUnix, 9), 'metric', MetricName, '' FROM cardo.bronze_otel_metrics_sum WHERE (MetricName = 'claude_code.session.count') AND ((Attributes['session.id']) != '') UNION ALL SELECT LogAttributes['session_id'], '', ResourceAttributes['cardo.salt_version'], '', '', '', '', Timestamp, 'collector', EventName, LogAttributes['session_end_reason'] FROM cardo.bronze_hook_events WHERE (LogAttributes['session_id']) != '') AS b LEFT JOIN (SELECT LogAttributes['session.id'] AS session_id, 'service' AS svc_kind, any(ResourceAttributes['cardo.workflow']) AS svc_workflow FROM cardo.bronze_otel_logs WHERE ((ResourceAttributes['cardo.actor']) = 'service') AND ((LogAttributes['session.id']) != '') GROUP BY session_id) AS svc USING (session_id) WHERE session_id NOT LIKE 'cardo-probe-%'
GROUP BY session_id;
